"""Tests for LiveSTLMonitor on trajectories generated by simulation.engine."""

from __future__ import annotations

import pytest
import numpy as np

from simulation.engine import run_simulation
from simulation.scenario import make_initial_agents
from simulation.schema import INSUFFICIENT_HISTORY, AgentState, AgentType
from verification.live_monitor import LiveSTLMonitor


@pytest.fixture(autouse=True)
def clean_boids_cache():
    """Clean module-level boids cache after test."""
    yield
    try:
        import local_behavior.boids as boids
        boids._last_corridor.clear()
    except Exception:
        pass


def test_live_monitor_on_sim_trajectory() -> None:
    """10 agents for 10 s: logged ticks == len(result.times), first tick neutral, finite rho values."""
    agents = make_initial_agents(10, seed=42)
    result = run_simulation(agents, duration_s=10.0)

    monitor = LiveSTLMonitor()
    n_ticks = len(result.times)
    n_agents = len(result.agent_ids)

    for k in range(n_ticks):
        t_k = float(result.times[k])
        those_agents = [
            AgentState(
                id=result.agent_ids[i],
                type=AgentType.DELIVERY,
                position=result.positions[k, i],
            )
            for i in range(n_agents)
        ]
        monitor.log_state(t_k, those_agents)

    # 1. Assert the number of logged ticks == len(result.times)
    assert len(monitor.history) == len(result.times)

    # 2. Assert the first tick is neutral (not a violation)
    first_record = monitor.history[0]
    assert first_record["status"] == INSUFFICIENT_HISTORY
    assert first_record["violation"] is False

    # 3. Assert all rho values are finite
    all_rho = [r["rho"] for r in monitor.history]
    assert np.all(np.isfinite(all_rho)), "Detected NaN or infinite robustness value"

